// PropScore AI — server-side login gate (Cloudflare Pages Functions).
//
// Runs before EVERY request, including index.html and images/, so nothing is
// served to a visitor without a valid session. The page embeds owner contact
// data, which is why this cannot be a JavaScript password box in the page.
//
// Required Cloudflare secrets — set them in the dashboard or with
// `wrangler pages secret put`, never in this file:
//   SITE_PASSWORD   the shared sign-in password
//   SESSION_SECRET  a long random string used to sign session cookies
// If either is missing the site fails CLOSED (503), never open.
// Changing SESSION_SECRET signs everyone out.

const COOKIE = "ps_session";
const SESSION_HOURS = 12;
const FAILED_LOGIN_DELAY_MS = 750;

export async function onRequest(context) {
  const { request, env, next } = context;
  const url = new URL(request.url);

  if (!env.SITE_PASSWORD || !env.SESSION_SECRET) {
    return new Response("Sign-in is not configured for this site.", {
      status: 503,
      headers: { "content-type": "text/plain; charset=utf-8", ...BASE_HEADERS },
    });
  }

  // Never serve this code or local tooling state, even to signed-in users.
  if (/^\/(functions|\.wrangler)(\/|$)/.test(url.pathname)) {
    return new Response("Not found", { status: 404, headers: BASE_HEADERS });
  }

  if (url.pathname === "/login") {
    if (request.method === "POST") return handleLogin(request, env);
    return loginPage({ next: safeNext(url.searchParams.get("next")) });
  }

  if (url.pathname === "/logout") {
    return new Response(null, {
      status: 303,
      headers: { location: "/login", "set-cookie": sessionCookie("", 0), ...BASE_HEADERS },
    });
  }

  if (await hasValidSession(request, env)) {
    return withPrivateCaching(await next());
  }

  if (request.method === "GET" || request.method === "HEAD") {
    const here = url.pathname + url.search;
    const location = here === "/" ? "/login" : "/login?next=" + encodeURIComponent(here);
    return new Response(null, { status: 302, headers: { location, ...BASE_HEADERS } });
  }
  return new Response("Unauthorized", { status: 401, headers: BASE_HEADERS });
}

// ---------------------------------------------------------------- sign-in

async function handleLogin(request, env) {
  const form = await request.formData().catch(() => null);
  const password = form ? String(form.get("password") ?? "") : "";
  const next = safeNext(form ? form.get("next") : null);

  if (!(await constantTimeEqual(password, env.SITE_PASSWORD))) {
    await new Promise((resolve) => setTimeout(resolve, FAILED_LOGIN_DELAY_MS));
    return loginPage({ next, error: "That password is incorrect", status: 401 });
  }

  const expires = Date.now() + SESSION_HOURS * 3600 * 1000;
  const token = `${expires}.${await sign(String(expires), env.SESSION_SECRET)}`;
  return new Response(null, {
    status: 303,
    headers: { location: next, "set-cookie": sessionCookie(token, SESSION_HOURS * 3600), ...BASE_HEADERS },
  });
}

async function hasValidSession(request, env) {
  const token = readCookie(request.headers.get("cookie"), COOKIE);
  if (!token) return false;
  const dot = token.indexOf(".");
  if (dot < 1) return false;
  const expires = token.slice(0, dot);
  const signature = token.slice(dot + 1);
  const expiresMs = Number(expires);
  if (!Number.isFinite(expiresMs) || expiresMs < Date.now()) return false;
  if (expiresMs > Date.now() + SESSION_HOURS * 3600 * 1000 + 60_000) return false;
  return constantTimeEqual(signature, await sign(expires, env.SESSION_SECRET));
}

// Only same-site relative paths, so ?next= can't bounce users to another domain.
function safeNext(value) {
  const v = typeof value === "string" ? value : "";
  if (!v.startsWith("/") || v.startsWith("//") || v.startsWith("/\\")) return "/";
  if (v === "/login" || v.startsWith("/login?") || v === "/logout") return "/";
  return v;
}

// ---------------------------------------------------------------- crypto

async function sign(value, secret) {
  const key = await crypto.subtle.importKey(
    "raw", new TextEncoder().encode(secret), { name: "HMAC", hash: "SHA-256" }, false, ["sign"],
  );
  const mac = await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(value));
  return base64url(new Uint8Array(mac));
}

// Hash both sides first so the comparison is fixed-length and timing-safe.
async function constantTimeEqual(a, b) {
  const [da, db] = await Promise.all([
    crypto.subtle.digest("SHA-256", new TextEncoder().encode(String(a))),
    crypto.subtle.digest("SHA-256", new TextEncoder().encode(String(b))),
  ]);
  const x = new Uint8Array(da);
  const y = new Uint8Array(db);
  let diff = 0;
  for (let i = 0; i < x.length; i++) diff |= x[i] ^ y[i];
  return diff === 0;
}

function base64url(bytes) {
  let s = "";
  for (const b of bytes) s += String.fromCharCode(b);
  return btoa(s).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

// ---------------------------------------------------------------- http helpers

const BASE_HEADERS = {
  "cache-control": "no-store",
  "x-robots-tag": "noindex, nofollow",
  "referrer-policy": "no-referrer",
};

function sessionCookie(value, maxAge) {
  return `${COOKIE}=${value}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=${maxAge}`;
}

function readCookie(header, name) {
  if (!header) return null;
  for (const part of header.split(";")) {
    const i = part.indexOf("=");
    if (i > -1 && part.slice(0, i).trim() === name) return part.slice(i + 1).trim();
  }
  return null;
}

// Authenticated responses must never land in a shared cache. The HTML also
// gets a Sign out button added to the existing top bar.
function withPrivateCaching(res) {
  const isHtml = (res.headers.get("content-type") || "").includes("text/html");
  const out = new Response(res.body, res);
  out.headers.set("cache-control", isHtml ? "private, no-store" : "private, max-age=86400");
  out.headers.set("x-robots-tag", "noindex, nofollow");
  if (!isHtml) return out;
  return new HTMLRewriter()
    .on("header.topbar", {
      element(el) {
        el.append(
          '<a href="/logout" style="margin-left:auto;color:#F8FAFC;font:600 13px/1 Manrope,system-ui,sans-serif;' +
            'text-decoration:none;padding:8px 12px;border:1px solid rgba(248,250,252,.35);border-radius:8px">Sign out</a>',
          { html: true },
        );
      },
    })
    .transform(out);
}

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, (c) =>
    ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c],
  );
}

// ---------------------------------------------------------------- page

function loginPage({ next = "/", error = "", status = 200 }) {
  const html = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="robots" content="noindex, nofollow">
<title>Sign in · PropScore AI</title>
<link rel="icon" type="image/png" href="data:image/png;base64,">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Trirong:wght@600;700&family=Manrope:wght@400;600;700&display=swap" rel="stylesheet">
<style>
:root{--navy:#082F7B;--blue:#1D4ED8;--ink:#0F172A;--muted:#64748B;--paper:#FAFAFA;--line:#E2E8F0;--cream:#F8FAFC;--amber:#B45309;--amber-bg:#FFFBEB}
*{box-sizing:border-box}
html{background:var(--navy)}
body{margin:0;min-height:100vh;display:flex;flex-direction:column;background:var(--paper);color:var(--ink);
  font:15px/1.5 Manrope,ui-sans-serif,system-ui,-apple-system,Segoe UI,sans-serif}
.topbar{display:flex;align-items:center;gap:13px;height:56px;padding:0 18px;background:var(--navy);color:var(--cream)}
.logo{height:30px;width:auto;display:block}
.brand{display:flex;flex-direction:column;gap:5px}
.brand h1{font:700 23px/1.05 Trirong,Georgia,serif;margin:0;letter-spacing:.01em}
.eyebrow{font-size:8.5px;letter-spacing:.16em;color:#93A9CE;margin:0;line-height:1;font-weight:600}
main{flex:1;display:flex;align-items:center;justify-content:center;padding:32px 16px}
.card{width:100%;max-width:380px;background:#fff;border:1px solid var(--line);border-radius:14px;
  padding:32px 28px;box-shadow:0 1px 2px rgba(15,23,42,.06),0 12px 32px rgba(8,47,123,.08)}
.card h2{font:700 24px/1.2 Trirong,Georgia,serif;margin:0 0 6px}
.lede{color:var(--muted);margin:0 0 24px;font-size:14px}
label{display:block;font-weight:600;font-size:13px;margin-bottom:6px}
input[type=password]{width:100%;font:inherit;padding:11px 12px;border:1px solid #CBD5E1;border-radius:9px;background:#fff;color:var(--ink)}
input[type=password]:focus{outline:none;border-color:var(--blue);box-shadow:0 0 0 3px rgba(29,78,216,.18)}
button{width:100%;margin-top:18px;font:700 15px/1 Manrope,system-ui,sans-serif;padding:13px;border:0;border-radius:9px;
  background:var(--navy);color:var(--cream);cursor:pointer}
button:hover{background:#0A3A96}
button:focus-visible{outline:3px solid rgba(29,78,216,.35);outline-offset:2px}
.error{background:var(--amber-bg);color:var(--amber);border:1px solid #FCD34D;border-radius:9px;padding:10px 12px;font-size:14px;margin:0 0 18px}
</style>
</head>
<body>
<header class="topbar">
  <img class="logo" src="data:image/png;base64," alt="">
  <div class="brand"><h1>PropScore AI</h1><p class="eyebrow">AI-POWERED PROPERTY SCREENING</p></div>
</header>
<main>
  <form class="card" method="post" action="/login" autocomplete="on">
    <h2>Sign in</h2>
    <p class="lede">Enter the password to continue.</p>
    ${error ? `<p class="error" role="alert">${escapeHtml(error)}</p>` : ""}
    <input type="hidden" name="next" value="${escapeHtml(next)}">
    <label for="password">Password</label>
    <input id="password" name="password" type="password" autocomplete="current-password" required autofocus>
    <button type="submit">Sign in</button>
  </form>
</main>
</body>
</html>`;
  return new Response(html, {
    status,
    headers: {
      "content-type": "text/html; charset=utf-8",
      "content-security-policy":
        "default-src 'none'; style-src 'unsafe-inline' https://fonts.googleapis.com; font-src https://fonts.gstatic.com; " +
        "img-src data:; form-action 'self'; frame-ancestors 'none'; base-uri 'none'",
      "x-frame-options": "DENY",
      ...BASE_HEADERS,
    },
  });
}
